"""Original sodium/water chapter: classify hyponatremia and its causes."""
from qbank_authoring import question,ref,finalize
HY=ref('European Clinical Practice Guideline: Hyponatraemia, 2014','https://academic.oup.com/ejendo/article/170/3/G1/6668028')
HS=ref('Austrian Society of Nephrology Consensus on Hyponatremia, 2024','https://link.springer.com/article/10.1007/s00508-024-02325-5')
DI=ref('Society for Endocrinology: Inpatient Management of Cranial Diabetes Insipidus','https://pmc.ncbi.nlm.nih.gov/articles/PMC6013691/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A sodium of 122 mmol/L is reported with normal measured serum osmolality and marked hypertriglyceridemia. Which explanation is most likely when sodium was measured by indirect ion-selective electrode?', 'Pseudohyponatremia from a reduced plasma water fraction',[
 ('True hypotonic hyponatremia caused by triglyceride osmotic activity','The measured osmolality and assay context favor an artifact.'),('Hypertonic hyponatremia from glucose','Glucose was not the identified abnormality.'),('SIAD established by sodium alone','SIAD requires hypotonicity and additional criteria.')],
 'Establish tonicity before classifying a low sodium', '**Indirect assays can underestimate sodium with extreme lipid or protein elevations.**',['Direct ion-selective measurement avoids the dilution-related artifact.','An actual water excess should not be assumed.'], '**Confirm the result before sodium-directed treatment.**',['Review measured osmolality and the analytical method.','True hypotonic disease can coexist and needs separate evaluation.'],[['Indirect electrode','Susceptible to water-fraction artifact'],['Direct electrode','Useful confirmation'],['Tonicity','Usually normal in isolated pseudohyponatremia']],[HY],'clinical_scenario')
q('Severe hyperglycemia accompanies hyponatremia and elevated effective osmolality. Which mechanism best explains the sodium fall?', 'Extracellular glucose draws water from cells and dilutes extracellular sodium',[
 ('Glucose causes pseudohyponatremia through the lipid displacement mechanism','This is a genuine translocational effect rather than the usual analytical artifact.'),('Primary water intoxication is proven','Effective osmolality is elevated rather than low.'),('Sodium loss is the sole necessary mechanism','Water redistribution can lower sodium even without primary sodium depletion.')],
 'Hypertonic hyponatremia differs from hypotonic disease', '**Glucose is an effective extracellular osmole.**',['A corrected sodium estimate helps assess water deficit.','Osmotic diuresis can create major additional fluid and electrolyte losses.'], '**Treat the hyperglycemic crisis with serial tonicity assessment.**',['Sodium commonly rises as glucose falls.','Interpret this rise with overall effective osmolality rather than in isolation.'],[['Glucose excess','Raises effective osmolality'],['Water shift','Cells to extracellular fluid'],['Sodium','Dilutional fall']],[HY],'clinical_scenario')
q('Which routinely measured solute contributes to calculated total osmolality but is relatively ineffective for steady-state tonicity across most cell membranes?', 'Urea',[
 ('Sodium salts','These are major determinants of extracellular tonicity.'),('Markedly elevated glucose','Glucose contributes effective extracellular osmotic pressure.'),('Mannitol','Mannitol can act as an effective extracellular osmole.')],
 'Total osmolality and tonicity are related but distinct', '**Urea crosses many cell membranes and contributes less sustained transcellular water shift.**',['Calculated effective osmolality usually excludes urea.','Rapid dialysis changes are a special disequilibrium context.'], '**Use the correct quantity for the clinical question.**',['A high urea can mask low effective osmolality in a total value.','Do not classify a hyponatremic patient from sodium alone.'],[['Total osmolality','Includes urea'],['Effective osmolality','Usually excludes urea'],['Dialysis','Rapid change can create gradients']],[HY])
q('Hypotonic hyponatremia is accompanied by urine osmolality of 65 mOsm/kg. What does this most strongly indicate?', 'Appropriate suppression of vasopressin with very dilute urine',[
 ('Persistent strong antidiuretic action as in typical SIAD','SIAD usually has urine osmolality above 100.'),('A diagnosis of primary adrenal insufficiency from this result alone','Adrenal insufficiency usually impairs free-water excretion.'),('Normal water intake is proven','Excess intake or low solute intake may still exceed excretory capacity.')],
 'Urine concentration is a functional readout of antidiuresis', '**Urine below about 100 mOsm/kg indicates near-maximal dilution.**',['Primary polydipsia and low dietary solute are important settings.','A mixed mechanism can evolve over time.'], '**Assess intake as well as urine output.**',['Correct low solute cautiously because brisk aquaresis can follow.','Repeat measurements when the clinical state changes.'],[['Urine below 100','Suppressed antidiuresis'],['Urine above 100','Impaired water excretion'],['Next inquiry','Water and solute intake']],[HY],'clinical_scenario')
q('A patient has hypotonic hyponatremia, urine osmolality 550 mOsm/kg and urine sodium 12 mmol/L before diuretics. Which interpretation is most likely?', 'Reduced effective arterial volume with renal sodium conservation',[
 ('SIAD is proven despite strong sodium conservation','Low urine sodium favors a different mechanism in this context.'),('Primary polydipsia with fully suppressed antidiuresis','The urine is highly concentrated.'),('Renal salt wasting is established','Urine sodium is low rather than inappropriately high.')],
 'Low effective volume can coexist with low total sodium or edema', '**Volume-mediated vasopressin secretion overrides the low plasma osmolality.**',['Gastrointestinal losses can reduce total extracellular volume.','Heart failure or cirrhosis can reduce effective arterial filling despite edema.'], '**Use the examination to distinguish these settings.**',['Recent diuretics and CKD can alter urine indices.','Treat the underlying circulation problem rather than assuming SIAD.'],[['Low urine sodium','Renal conservation'],['Concentrated urine','Antidiuretic effect'],['Clinical distinction','Depletion versus edematous underfilling']],[HY],'clinical_scenario')
q('Which set of findings most supports SIAD after appropriate exclusions?', 'Hypotonic euvolemic hyponatremia with urine osmolality above 100 and urine sodium generally above 30 mmol/L',[
 ('Hypertonicity and very dilute urine','These do not fit the usual SIAD pattern.'),('Hypovolemia with appropriate renal sodium conservation','This suggests a volume-mediated mechanism.'),('Hyponatremia during untreated cortisol deficiency without further assessment','Cortisol deficiency must be excluded before assigning SIAD.')],
 'SIAD is a diagnosis of exclusion', '**Persistent antidiuresis is inappropriate for the plasma tonicity.**',['Adequate thyroid, adrenal and kidney assessment is necessary.','Recent diuretics can confound the apparent euvolemic pattern.'], '**Identify medications and pulmonary or CNS triggers.**',['Small-cell lung cancer is a classic association.','The diagnostic label does not determine emergency treatment when symptoms are severe.'],[['Plasma','Hypotonic'],['Urine','Inappropriately concentrated'],['Exclusions','Adrenal, thyroid, renal and diuretic causes']],[HY])
q('Why can secondary adrenal insufficiency resemble SIAD?', 'Cortisol deficiency permits persistent vasopressin-mediated water retention despite relatively preserved aldosterone',[
 ('It necessarily causes profound renal potassium wasting','This is not the defining mechanism.'),('It invariably causes hyperkalemia equal to primary adrenal failure','Aldosterone is often preserved in central disease.'),('It prevents vasopressin secretion','Cortisol deficiency instead promotes antidiuresis.')],
 'Normal potassium does not exclude cortisol deficiency', '**Central adrenal failure may present with euvolemic-appearing hyponatremia.**',['Primary adrenal failure also causes mineralocorticoid-related volume and potassium abnormalities.','Glucocorticoid treatment may trigger a brisk water diuresis.'], '**Evaluate adrenal function before confirming SIAD.**',['Treat suspected adrenal crisis urgently.','Monitor sodium after hormone replacement for overcorrection.'],[['Secondary failure','Cortisol deficit; aldosterone often preserved'],['Primary failure','Cortisol and mineralocorticoid deficits'],['After treatment','Water excretion can increase']],[HY])
q('An older patient develops hyponatremia soon after starting hydrochlorothiazide. Which feature explains why thiazides are more prone than loop diuretics to cause this disorder?', 'They impair urinary dilution while leaving the medullary concentrating mechanism relatively preserved',[
 ('They completely abolish the medullary gradient like loop agents','That is more characteristic of loop diuretics.'),('They directly produce vasopressin deficiency','That would promote dilute water loss.'),('They prevent all potassium losses','Thiazides can cause potassium depletion, which may worsen hyponatremia.')],
 'The site of diuretic action matters', '**Distal convoluted tubular sodium-chloride blockade reduces free-water clearance.**',['Low solute intake, older age and excess water increase susceptibility.','The biochemical pattern can mimic SIAD.'], '**Stop the implicated drug and treat according to symptoms and volume.**',['Monitor for aquaresis after withdrawal.','Potassium replacement also influences the sodium trajectory.'],[['Thiazide','Impaired dilution'],['Loop','Disrupts concentrating gradient'],['Risk','Water intake plus susceptibility']],[HY],'clinical_scenario')
q('A malnourished heavy beer drinker has profound hypotonic hyponatremia with little food intake. Why can sodium rise abruptly after nutrition or saline?', 'Restoring solute delivery can abruptly increase renal water excretion',[
 ('Beer produces permanent inability to dilute urine','The defect can be limited solute excretion rather than fixed renal damage.'),('Dietary protein never affects water clearance','Urea generation from protein contributes urinary osmoles.'),('A low initial sodium protects against osmotic demyelination','Profound chronic hyponatremia increases risk.')],
 'Water excretion is constrained by available osmoles', '**Even dilute urine has a finite daily volume when solute intake is very low.**',['Protein and salt repletion can remove this constraint.','Alcohol use and malnutrition also increase demyelination risk.'], '**Introduce treatment with close sodium and urine monitoring.**',['Anticipate spontaneous aquaresis.','Be ready to prevent or reverse an excessive rise.'],[['Low solute','Limited excretory capacity'],['Solute restoration','Potential brisk aquaresis'],['High-risk host','Strict correction limits']],[HY,HS],'clinical_scenario')
q('In chronic SIAD without severe symptoms, which is a common initial management component?', 'Treat the cause and restrict fluid intake when appropriate',[
 ('Rapidly normalize sodium with repeated hypertonic boluses regardless of symptoms','Boluses are for significant symptomatic emergencies, not routine normalization.'),('Give unrestricted hypotonic fluid','This generally worsens water excess.'),('Continue the causal drug whenever sodium is low','Causal medications should be reviewed when feasible.')],
 'Treatment intensity should match symptoms and chronicity', '**Fluid restriction reduces intake below water excretory capacity.**',['It may fail when urine is very concentrated or adherence is impractical.','Underlying disease treatment and medication review remain central.'], '**Escalate using a monitored individualized plan.**',['Options can include oral urea in appropriate settings.','Vaptans require careful indication, contraindication and overcorrection assessment.'],[['Initial approach','Cause treatment and fluid restriction'],['Failure predictors','High urine concentration'],['Escalation','Monitored specialist selection']],[HY,HS])
q('Why can isotonic saline fail to correct or even worsen sodium in SIAD with highly concentrated urine?', 'The kidney can excrete infused sodium in a relatively small urine volume while retaining part of the infused water',[
 ('Isotonic saline contains no sodium','It contains about 154 mmol/L sodium.'),('All saline is chemically hypotonic before infusion','The problem is the renal response, not absence of sodium in the bag.'),('SIAD always causes obligatory dilute polyuria','The urine is inappropriately concentrated.')],
 'Infused tonicity does not by itself predict retained tonicity', '**Desalination can occur when urinary electrolyte concentration is high.**',['This contrasts with appropriate saline replacement in true volume depletion.','Mixed causes make serial assessment essential.'], '**Avoid automatic saline for every low sodium.**',['Confirm the mechanism and symptoms.','Monitor the biochemical response to any administered fluid.'],[['Volume depletion','Saline can remove volume stimulus'],['Concentrated SIAD urine','Potential desalination'],['Safety','Serial sodium and urine assessment']],[HY])
q('A patient with hyponatremia and clear extracellular volume depletion has no severe neurological symptoms. Which treatment usually addresses the main mechanism?', 'Restore extracellular volume with an appropriate isotonic crystalloid while treating ongoing losses',[
 ('Fluid restriction alone despite hypotension','This does not correct the circulation deficit.'),('Tolvaptan as first-line treatment of hypovolemia','Aquaresis can worsen volume depletion.'),('D5W as the sole initial resuscitation fluid in shock','Free-water replacement is not the appropriate initial circulatory resuscitation.')],
 'Correct the appropriate non-osmotic vasopressin stimulus', '**Restoring effective volume can turn off antidiuresis.**',['Gastrointestinal losses, diuretics and bleeding require targeted treatment.','Volume restoration can then provoke rapid dilute urine output.'], '**Monitor sodium closely during recovery.**',['A sudden aquaresis can cause overshoot.','Use symptom-directed emergency therapy if severe neurological signs develop.'],[['Initial defect','Volume depletion'],['Therapy','Appropriate isotonic replacement'],['Later risk','Water diuresis and sodium overshoot']],[HY],'clinical_scenario')
q('Hyponatremia occurs in a patient with ascites and peripheral edema from advanced cirrhosis. What is the principal water-retaining stimulus?', 'Reduced effective arterial filling despite increased total extracellular fluid',[
 ('An expanded effective arterial circulation suppressing all vasopressin','Splanchnic vasodilation creates perceived underfilling.'),('A mandatory analytical artifact from low albumin','This does not explain typical dilutional hyponatremia.'),('Isolated sodium intake with no water physiology','Antidiuresis and circulatory changes are central.')],
 'Edema does not equal adequate effective circulation', '**Non-osmotic vasopressin promotes water retention.**',['Total body sodium can also be increased.','Renal sodium conservation may coexist with ascites.'], '**Treat the circulatory and liver disease context.**',['Review diuretics, kidney function and fluid strategy.','Avoid reflex saline loading solely because sodium is low.'],[['Total extracellular fluid','Increased'],['Effective filling','Reduced'],['Consequence','Water retention and dilution']],[HY],'clinical_scenario')
q('After subarachnoid hemorrhage, a patient has hyponatremia, high urine sodium, polyuria and convincing volume depletion. Which distinction is most important?', 'Renal salt wasting can resemble SIAD biochemically but requires a different volume strategy',[
 ('High urine sodium alone definitively proves SIAD','Volume depletion and other causes must be considered.'),('Every CNS-associated hyponatremia needs water restriction regardless of perfusion','Restriction can worsen true volume depletion.'),('Cortisol deficiency no longer needs exclusion after brain injury','Adrenal dysfunction remains a competing cause.')],
 'A similar urine pattern can arise from different mechanisms', '**Salt wasting involves net sodium loss and volume depletion.**',['SIAD is usually clinically euvolemic.','Reliable volume assessment can be difficult in critical illness.'], '**Use serial balance and the neurological context.**',['Restore deficits when salt wasting is established.','Do not rely on a single spot sodium or urate result in isolation.'],[['SIAD','Water retention without clear depletion'],['Salt wasting','Sodium loss with depletion'],['Decision','Serial integrated assessment']],[HY],'clinical_scenario')
q('Which medication class is a well-recognized cause of SIAD-like hyponatremia?', 'Selective serotonin reuptake inhibitors',[
 ('Vasopressin antagonists through increased V2 signaling','They antagonize rather than stimulate V2-mediated water retention.'),('Loop diuretics solely through the same mechanism as SSRIs','Their renal transport effects are different.'),('Oral urea through suppression of urinary osmole excretion','Urea increases osmole excretion and can be therapeutic.')],
 'Medication timing is part of the causal assessment', '**SSRIs can promote inappropriate antidiuresis.**',['Older age, concurrent drugs and low baseline sodium can increase risk.','Carbamazepine and several other agents are additional triggers.'], '**Review a safe alternative with the prescriber.**',['Do not overlook other causes merely because a possible drug exists.','Sodium can rise after withdrawal, so monitor correction.'],[['Drug clue','Recent initiation or dose change'],['Mechanism','Increased antidiuresis'],['Action','Causality and regimen review']],[HY])
q('A patient with chronic low sodium remains stable at 128–131 mmol/L, has preserved ability to dilute urine under supervised assessment and no progressive disorder. Which mechanism can explain this pattern?', 'A reset osmotic threshold for vasopressin release',[
 ('Persistent maximal vasopressin action at every osmolality','Preserved dilution argues against fixed maximal antidiuresis.'),('Pseudohyponatremia is proven by stability alone','Tonicity and assay information are required.'),('A sodium level in this range excludes all endocrine disease','Appropriate exclusions are still necessary.')],
 'The regulated set point can shift downward', '**A reset osmostat maintains sodium around a lower threshold.**',['This diagnosis requires careful exclusion of other causes.','Unsupervised water-loading tests can be hazardous and are not routine.'], '**Avoid reflex escalation solely to normalize a stable number.**',['Review symptoms, trajectory and underlying conditions.','Individualize monitoring and treatment need.'],[['Pattern','Stable modest hyponatremia'],['Physiology','Preserved regulation at lower set point'],['Diagnosis','Requires exclusions']],[HY])
q('Which urine finding predicts that fluid restriction may be difficult to use effectively in SIAD?', 'Urine sodium plus potassium approaching or exceeding plasma sodium',[
 ('Very dilute urine with suppressed antidiuresis','That suggests a different physiology with greater free-water excretion.'),('Urine osmolality below 100 in all samples','This is not the usual persistent SIAD pattern.'),('A low urine electrolyte concentration proving no solute excretion','Low concentration does not prove absent osmole excretion.')],
 'Electrolyte-free water clearance helps interpret restriction', '**If urine sodium plus potassium exceeds plasma sodium, the urine removes little or negative electrolyte-free water.**',['High urine osmolality and low urine volume also predict poor response.','The ratio does not replace a complete clinical assessment.'], '**Consider feasibility and monitored alternatives.**',['Ensure adequate solute intake.','Review the cause and avoid excessive restriction that compromises nutrition.'],[['Urine electrolyte ratio','Reflects free-water handling'],['High ratio','Restriction more difficult'],['Clinical response','Requires repeat assessment']],[HY,HS])
q('What is the principal role of oral urea in selected patients with chronic SIAD?', 'Increasing urinary osmole excretion to permit more water excretion',[
 ('Directly blocking the mineralocorticoid receptor','Urea is not a mineralocorticoid antagonist.'),('Replacing cortisol in adrenal insufficiency','Hormonal deficiency needs appropriate hormone replacement.'),('Providing rapid emergency reversal of seizures as the standard first choice','Severe symptomatic disease requires controlled hypertonic saline.')],
 'Solute therapy changes water excretory capacity', '**Urea can create an osmotic water-excretion effect.**',['Taste, adherence and availability matter.','A rise in blood urea during therapy does not necessarily mean kidney injury.'], '**Monitor sodium after initiation or dose changes.**',['Overcorrection remains possible with changing disease physiology.','Use a supervised plan after appropriate diagnostic exclusions.'],[['Action','More urinary osmoles'],['Use','Selected chronic SIAD'],['Monitoring','Sodium and response']],[HY,HS])
